#include <windows.h>
#include <string>
#include <cwchar>
static void put(const wchar_t *path,const std::string &text){HANDLE f=CreateFileW(path,GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,nullptr);if(f!=INVALID_HANDLE_VALUE){DWORD n;WriteFile(f,text.data(),DWORD(text.size()),&n,nullptr);CloseHandle(f);}}
int wmain(int argc,wchar_t **argv){if(argc<3)return 2;const std::wstring prefix=argv[2];if(std::wcscmp(argv[1],L"--worker")==0){put((prefix+L".worker").c_str(),std::to_string(GetCurrentProcessId()));Sleep(5000);put((prefix+L".late").c_str(),"unwanted output after abort");return 0;}wchar_t path[32768];GetModuleFileNameW(nullptr,path,32768);std::wstring command=L"\""+std::wstring(path)+L"\" --worker \""+prefix+L"\"";STARTUPINFOW start{};start.cb=sizeof(start);PROCESS_INFORMATION process{};if(!CreateProcessW(nullptr,command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,nullptr,&start,&process))return 3;CloseHandle(process.hThread);if(std::wcscmp(argv[1],L"--detach")==0){CloseHandle(process.hProcess);return 0;}WaitForSingleObject(process.hProcess,INFINITE);CloseHandle(process.hProcess);return 0;}